import sys,collections,heapq,itertools,functools,bisect
def solve(data):
    a=list(map(int,data.split()));n,T=a[:2];v=a[2:]
    def f(i,s):
        if i==n:return int(s==T)
        return f(i+1,s+v[i])+f(i+1,s-v[i])
    return f(1,v[0])

if __name__=="__main__":
    a=solve(sys.stdin.buffer.read().decode())
    print(" ".join(map(str,a)) if isinstance(a,(list,tuple)) else a)
